#!/usr/bin/env python3
"""Branch cleanup command implemented with Git's public plumbing interface."""
import os
import re
import sys
import subprocess
from dataclasses import dataclass

DESCRIPTION = 'Automatically trims your tracking branches whose upstream branches are merged or stray.'
LONG_DESCRIPTION = '`git-trim` is a missing companion to the `git fetch --prune` and a proper, safer, faster alternative to your `<bash oneliner HERE>`.'
BASE_HELP = 'Comma separated multiple names of branches. All the other branches are compared with the upstream branches of those branches. [default: branches that tracks `git symbolic-ref refs/remotes/*/HEAD`] [config: trim.bases]'
BASE_LONG = 'The default value is a branch that tracks `git symbolic-ref refs/remotes/*/HEAD`. They might not be reflected correctly when the HEAD branch of your remote repository is changed. You can see the changed HEAD branch name with `git remote show <remote>` and apply it to your local repository with `git remote set-head <remote> --auto`.'
DELETE_HELP = 'Comma separated values of `<delete range>[:<remote name>]`. Delete range is one of the `merged, merged-local, merged-remote, stray, diverged, local, remote`. `:<remote name>` is only necessary to a `<delete range>` when the range is applied to remote branches. You can use `*` as `<remote name>` to delete a range of branches from all remotes. [default : `merged:origin`] [config: trim.delete]'
DELETE_LONG = '`merged-local` will delete merged tracking local branches. `merged-remote:<remote>` will delete merged upstream branches from `<remote>`. `stray` will delete tracking local branches, which is not merged, but the upstream is gone. `diverged:<remote>` will delete merged tracking local branches, and their upstreams from `<remote>` even if the upstreams are not merged and diverged from local ones. `local` will delete non-tracking merged local branches. `remote:<remote>` will delete non-upstream merged remote tracking branches. Use with caution when you are using other than `merged`. It might lose changes, and even nuke repositories.'
HELP_OPTIONS = [
    ('-b', '--bases', 'BASES', BASE_HELP),
    ('-p', '--protected', 'PROTECTED', 'Comma separated multiple glob patterns (e.g. `release-*`, `feature/*`) of branches that should never be deleted. [config: trim.protected]'),
    ('', '--no-update', '', 'Do not update remotes [config: trim.update]'),
    ('', '--update-interval', 'UPDATE_INTERVAL', 'Prevents too frequent updates. Seconds between updates in seconds. 0 to disable. [default: 5] [config: trim.updateInterval]'),
    ('', '--no-confirm', '', 'Do not ask confirm [config: trim.confirm]'),
    ('', '--no-detach', '', 'Do not detach when HEAD is about to be deleted [config: trim.detach]'),
    ('-d', '--delete', 'DELETE', DELETE_HELP),
    ('', '--dry-run', '', 'Do not delete branches, show what branches will be deleted'),
    ('-h', '--help', '', ''),
    ('-V', '--version', '', 'Print version'),
]


def out(s=''):
    print(s, flush=True)


def err(s=''):
    print(s, file=sys.stderr, flush=True)


class Failure(Exception):
    pass


class Exit(Exception):
    def __init__(self, code=0):
        self.code = code


def color_enabled(stream):
    if os.environ.get('NO_COLOR'):
        return False
    if os.environ.get('CLICOLOR_FORCE', '0') != '0':
        return True
    return stream.isatty() and os.environ.get('TERM') != 'dumb'


def help_text(long, name):
    bold = lambda s: '\x1b[1m' + s + '\x1b[0m' if color_enabled(sys.stdout) else s
    heading = lambda s: '\x1b[1m\x1b[4m' + s + '\x1b[0m' if color_enabled(sys.stdout) else s
    lines = [DESCRIPTION]
    if long:
        lines.append(LONG_DESCRIPTION)
    lines.extend(['', heading('Usage:') + ' ' + bold(name) + ' [OPTIONS]', '', heading('Options:')])
    for sh, flag, value, desc in HELP_OPTIONS:
        if flag == '--help':
            desc = "Print help (see a summary with '-h')" if long else "Print help (see more with '--help')"
        prefix = '  ' + bold(sh) + ', ' if sh else '      '
        lines.append(prefix + bold(flag) + (' <' + value + '>' if value else ''))
        lines.append('          ' + desc)
        if long and flag == '--bases':
            lines.extend(['          ', '          ' + BASE_LONG])
        if long and flag == '--delete':
            lines.extend(['          ', '          `merged` implies `merged-local,merged-remote`.', '          ', '          ' + DELETE_LONG])
        if long and flag != '--version':
            lines.append('')
    return '\n'.join(lines) + '\n'


def delete_token(value):
    token = value.strip()
    if token in ('merged-local', 'stray', 'local'):
        return [(token, None)]
    if ':' in token:
        typ, scope = token.split(':', 1)
        typ, scope = typ.strip(), scope.strip()
        if typ in ('merged', 'merged-remote', 'diverged', 'remote'):
            if not scope:
                raise Failure('Scope parse error for delete range while parsing scope: Scope is empty')
            if typ == 'merged':
                return [('merged-local', None), ('merged-remote', scope)]
            return [(typ, scope)]
    raise Failure('Invalid delete range format `' + value + '`')


class Options:
    def __init__(self):
        self.bases = None
        self.protected = None
        self.delete = None
        self.update_interval = None
        self.no_update = False
        self.no_confirm = False
        self.no_detach = False
        self.dry_run = False


def parse_args(args):
    opts = Options()
    name = os.path.basename(sys.argv[0]) or 'executable'
    flags = {row[1]: row[2] for row in HELP_OPTIONS}
    short = {row[0][1:]: row[1] for row in HELP_OPTIONS if row[0]}
    seen = set()

    def error(message, usage=None):
        err('error: ' + message)
        err()
        if usage is not None:
            err('Usage: ' + name + ' ' + usage)
            err()
        err("For more information, try '--help'.")
        raise Exit(2)

    def unknown(arg):
        tip = None
        if arg.startswith('--'):
            # Clap offers suggestions only for relatively similar option names.
            import difflib
            close = difflib.get_close_matches(arg, flags.keys(), 1, .77)
            if close:
                tip = close[0]
        message = "unexpected argument '" + arg + "' found"
        if tip:
            message += "\n\n  tip: a similar argument exists: '" + tip + "'"
        error(message, '[OPTIONS]')

    def consume(flag, value):
        if flag in ('--help', '--version'):
            if value is not None:
                error("unexpected value '" + value + "' for '" + flag + "' found; no more were expected", flag)
            if flag == '--version':
                out('git-trim 0.4.4')
            else:
                sys.stdout.write(help_text(True, name)); sys.stdout.flush()
            raise Exit()
        key = flag[2:].replace('-', '_')
        if flags[flag]:
            if flag in ('--bases', '--protected'):
                if getattr(opts, key) is None:
                    setattr(opts, key, [])
                getattr(opts, key).extend(value.split(','))
            elif flag == '--delete':
                if opts.delete is None:
                    opts.delete = []
                for token in value.split(','):
                    try:
                        opts.delete.extend(delete_token(token))
                    except Failure as e:
                        error("invalid value '" + token + "' for '--delete <DELETE>': " + str(e))
            else:
                if flag in seen:
                    error("the argument '--update-interval <UPDATE_INTERVAL>' cannot be used multiple times", '[OPTIONS]')
                why = None
                if not value:
                    why = 'cannot parse integer from empty string'
                elif not re.fullmatch(r'\+?[0-9]+', value):
                    why = 'invalid digit found in string'
                elif int(value) > 18446744073709551615:
                    why = 'number too large to fit in target type'
                if why:
                    error("invalid value '" + value + "' for '--update-interval <UPDATE_INTERVAL>': " + why)
                opts.update_interval = int(value)
        else:
            if value is not None:
                error("unexpected value '" + value + "' for '" + flag + "' found; no more were expected", flag)
            if flag in seen:
                error("the argument '" + flag + "' cannot be used multiple times", '[OPTIONS]')
            setattr(opts, key, True)
        seen.add(flag)

    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if arg == '--':
            if i != len(args):
                unknown(args[i])
            break
        if arg.startswith('--'):
            flag, eq, val = arg.partition('=')
            if flag not in flags:
                unknown(flag)
            value = val if eq else None
            if flags[flag] and not eq:
                if i == len(args):
                    error("a value is required for '" + flag + ' <' + flags[flag] + ">' but none was supplied")
                if args[i].startswith('-') and args[i] != '-':
                    if args[i] in ('-h', '--help'):
                        sys.stdout.write(help_text(args[i] == '--help', name)); sys.stdout.flush(); raise Exit()
                    if args[i] in flags:
                        error("a value is required for '" + flag + ' <' + flags[flag] + ">' but none was supplied")
                    unknown(args[i])
                value = args[i]; i += 1
            consume(flag, value)
        elif arg.startswith('-') and arg != '-':
            chars = arg[1:]
            while chars:
                sh, chars = chars[0], chars[1:]
                if sh not in short:
                    unknown('-' + sh)
                flag = short[sh]
                if flag == '--help':
                    sys.stdout.write(help_text(False, name)); sys.stdout.flush(); raise Exit()
                value = None
                if flags[flag]:
                    if chars:
                        value = chars[1:] if chars.startswith('=') else chars
                        chars = ''
                    else:
                        if i == len(args):
                            error("a value is required for '" + flag + ' <' + flags[flag] + ">' but none was supplied")
                        if args[i].startswith('-') and args[i] != '-':
                            if args[i] in ('-h', '--help'):
                                sys.stdout.write(help_text(args[i] == '--help', name)); sys.stdout.flush(); raise Exit()
                            if args[i] in flags or args[i] in [r[0] for r in HELP_OPTIONS]:
                                error("a value is required for '" + flag + ' <' + flags[flag] + ">' but none was supplied")
                            unknown(args[i])
                        value = args[i]; i += 1
                consume(flag, value)
        else:
            unknown(arg)
    return opts


def git(*args, cwd=None, env=None, data=None, visible=False):
    try:
        return subprocess.run(['git', *args], cwd=cwd, env=env, input=data,
                              stdout=None if visible else subprocess.PIPE,
                              stderr=None if visible else subprocess.PIPE)
    except FileNotFoundError:
        raise Failure('No such file or directory (os error 2)')
    except OSError as e:
        raise Failure(str(e.strerror) + ' (os error ' + str(e.errno) + ')')


def text(data):
    return data.decode('utf-8', errors='replace')


def gittext(*args):
    p = git(*args)
    return text(p.stdout).strip() if p.returncode == 0 else ''


def status_error(status):
    if status >= 0:
        try:
            desc = os.strerror(status)
        except ValueError:
            desc = 'Unknown error ' + str(status)
        raise Failure(desc + ' (os error ' + str(status) + ')')
    raise Failure('process terminated by a signal')


def visible_git(*args):
    sys.stdout.flush(); sys.stderr.flush()
    p = git(*args, visible=True)
    if p.returncode:
        status_error(p.returncode)


class Config:
    def __init__(self):
        self.entries = {}
        p = git('config', '--null', '--list')
        if p.returncode:
            raise Failure('failed to read configuration')
        for item in text(p.stdout).split('\0'):
            if not item:
                continue
            key, sep, val = item.partition('\n')
            self.entries.setdefault(key, []).append(val if sep else None)

    def all(self, key):
        return self.entries.get(key)

    def get(self, key, default=None):
        vals = self.all(key)
        return vals[-1] if vals else default

    def boolean(self, key, default):
        vals = self.all(key)
        if vals is None:
            return default
        v = vals[-1]
        if v is None:
            return True
        low = v.lower()
        if low in ('yes', 'true', 'on'):
            return True
        if low in ('no', 'false', 'off', ''):
            return False
        try:
            return parse_git_int(v) != 0
        except ValueError:
            raise Failure("failed to parse '" + v + "' as a boolean value; class=Config (7)")

    def integer(self, key, default):
        vals = self.all(key)
        if vals is None:
            return default
        v = vals[-1] or ''
        try:
            return parse_git_int(v)
        except ValueError:
            raise Failure("failed to parse '" + v + "' as an integer; class=Config (7)")

    def comma_list(self, key):
        vals = self.all(key)
        if vals is None:
            return None
        return [t for val in vals for t in (val or '').split(',') if t != '']


def parse_git_int(s):
    m = re.fullmatch(r'([+-]?[0-9]+)([kKmMgG]?)', s)
    if not m:
        raise ValueError()
    v = int(m[1]) * {'': 1, 'k': 1024, 'm': 1024**2, 'g': 1024**3}[m[2].lower()]
    if not -(1 << 63) <= v < (1 << 63):
        raise ValueError()
    return v


@dataclass
class Branch:
    ref: str
    oid: str
    symbolic: str = ''
    upstream: str = ''
    remote: str = ''
    remote_ref: str = ''
    tracking: bool = False
    direct: bool = False
    unknown: bool = False

    @property
    def local(self):
        return self.ref.startswith('refs/heads/')

    @property
    def name(self):
        return self.ref[len('refs/heads/'):] if self.local else self.ref[len('refs/remotes/'):]


@dataclass
class Base:
    ref: str
    pattern: str
    local: str = ''


class Repository:
    def __init__(self):
        p = git('rev-parse', '--absolute-git-dir')
        if p.returncode:
            raise Failure("could not find repository at '.'; class=Repository (6); code=NotFound (-3)")
        self.gitdir = text(p.stdout).strip()
        self.bare = gittext('rev-parse', '--is-bare-repository') == 'true'
        self.common = gittext('rev-parse', '--path-format=absolute', '--git-common-dir')
        if not os.path.isabs(self.common):
            self.common = os.path.abspath(self.common)
        root = gittext('rev-parse', '--show-toplevel')
        if not root and not self.bare:
            ptr = os.path.join(self.gitdir, 'gitdir')
            if os.path.isfile(ptr):
                with open(ptr, encoding='utf-8') as f:
                    root = os.path.dirname(f.read().strip())
            else:
                root = os.path.dirname(self.gitdir)
        self.root = root or self.gitdir
        os.chdir(self.root)
        self.config = Config()
        self.remotes = gittext('remote').splitlines()
        if not self.remotes:
            raise Failure('git-trim requires at least one remote')
        self.head = gittext('symbolic-ref', '-q', 'HEAD')
        self.refs = {}
        self.locals = []
        self.remote_branches = []
        self.load_refs()

    def load_refs(self):
        fmt = '%(refname)%00%(objectname)%00%(symref)%00%(upstream)'
        p = git('for-each-ref', '--format=' + fmt, 'refs/heads/', 'refs/remotes/')
        if p.returncode:
            status_error(p.returncode)
        rows = []
        for line in text(p.stdout).splitlines():
            parts = line.split('\0')
            if len(parts) >= 4:
                rows.append(parts)
        rows.sort(key=lambda row: (not os.path.isfile(os.path.join(self.common, row[0])), row[0]))
        self.refs = {}
        self.locals = []
        self.remote_branches = []
        for ref, oid, symref, upstream in rows:
            b = Branch(ref, oid, symref, upstream)
            self.refs[ref] = b
            if b.local:
                self.locals.append(b)
            elif not symref:
                self.remote_branches.append(b)
        for b in self.locals:
            remote = self.config.get('branch.' + b.name + '.remote')
            merge = self.config.get('branch.' + b.name + '.merge')
            b.remote = remote or ''
            b.remote_ref = merge or ''
            b.tracking = remote is not None
            if not b.tracking:
                continue
            if remote not in self.remotes and remote != '.' and '/' not in (remote or '') and ':' not in (remote or ''):
                # Kept for validation after configuration has been assembled.
                b.unknown = True
            if not merge:
                b.unknown = True
            if not b.upstream:
                b.upstream = self.map_fetch(remote, merge) or ''
            b.direct = bool(merge) and (not b.upstream or not b.upstream.startswith('refs/remotes/'))

    def map_fetch(self, remote, source):
        if not source:
            return None
        if remote == '.':
            return source
        for spec in self.config.all('remote.' + (remote or '') + '.fetch') or []:
            if not spec or spec.startswith('^'):
                continue
            pair = spec.lstrip('+').split(':', 1)
            if len(pair) != 2:
                continue
            src, dst = pair
            if '*' in src:
                pre, suf = src.split('*', 1)
                if source.startswith(pre) and source.endswith(suf):
                    mid = source[len(pre):len(source)-len(suf) if suf else None]
                    return dst.replace('*', mid)
            elif src == source:
                return dst
        return None

    def remote_source(self, ref):
        for remote in sorted(self.remotes, key=lambda r: (-len(r), r)):
            for spec in self.config.all('remote.' + remote + '.fetch') or []:
                if not spec or spec.startswith('^'):
                    continue
                pair = spec.lstrip('+').split(':', 1)
                if len(pair) != 2:
                    continue
                src, dst = pair
                if '*' in dst:
                    pre, suf = dst.split('*', 1)
                    if ref.startswith(pre) and ref.endswith(suf):
                        mid = ref[len(pre):len(ref)-len(suf) if suf else None]
                        return remote, src.replace('*', mid)
                elif ref == dst:
                    return remote, src
        short = ref.removeprefix('refs/remotes/')
        if '/' in short:
            remote, name = short.split('/', 1)
            return remote, 'refs/heads/' + name
        return '', ref

    def defaults(self):
        heads = []
        for remote in self.remotes:
            h = self.refs.get('refs/remotes/' + remote + '/HEAD')
            if h:
                ref = h.symbolic or h.ref
                if ref in self.refs:
                    heads.append(ref)
        locals = [b.name for b in self.locals if b.tracking and b.upstream in heads]
        return locals or [h.removeprefix('refs/remotes/') for h in heads]

    def validate_branches(self):
        for b in self.locals:
            if b.tracking and b.remote not in self.remotes and b.remote != '.' and '/' not in b.remote and ':' not in b.remote:
                raise Failure("remote '" + b.remote + "' does not exist; class=Config (7); code=NotFound (-3)")

    def resolve_bases(self, patterns):
        bases = []
        for pattern in dict.fromkeys(patterns):
            if git('check-ref-format', '--allow-onelevel', pattern).returncode != 0:
                raise Failure("could not use '" + pattern + "' as valid reference name; class=Reference (4); code=InvalidSpec (-12)")
            ref = gittext('rev-parse', '--symbolic-full-name', '--verify', pattern)
            if not ref:
                continue
            if ref not in self.refs:
                if ref.startswith('refs/'):
                    raise Failure('Reference Some("' + ref + '") is not a branch')
                continue
            branch = self.refs[ref]
            if branch.symbolic:
                ref = branch.symbolic
                branch = self.refs.get(ref)
                if not branch:
                    continue
            if branch.local:
                if branch.upstream in self.refs and not branch.direct:
                    bases.append(Base(branch.upstream, pattern, branch.ref))
            else:
                bases.append(Base(branch.ref, pattern))
        return bases


def no_bases(repo, from_config=False):
    if from_config:
        err('I found that `git config trim.bases` is empty! Try any following commands to set valid bases:')
    else:
        err("I can't detect base branch! Try following any resolution:")
        if len(repo.remotes) == 1:
            remote = repo.remotes[0]
            err(' * `git remote set-head ' + remote + ' --auto` will help `git-trim` to automatically\n'
                '   detect the base branch.\n'
                '   If you see `' + remote + '/HEAD set to <base branch>` in the output of the previous\n'
                '   command, then `git branch --set-upstream ' + remote + '/<base branch> <base branch>`\n'
                '   to set an upstream branch for <base branch> if exists.')
        else:
            err(' * `git remote set-head <remote> --auto` will help `git-trim` to automatically\n'
                '   detect the base branch.\n'
                '   Following command will sync all remotes for you:\n'
                '   `for REMOTE in $(git remote); do git remote set-head "$REMOTE" --auto; done`\n'
                '   Pick an appropriate one in mind if you see multiple `<remote>/HEAD set to\n'
                '   <base branch>` in the output of the previous command.\n'
                '   Then `git branch --set-upstream <remote>/<base branch> <base branch>` to set\n'
                '   an upstream branch for <base branch> if exists.')
        out('You also can set bases manually with any of following commands:')
    err(' * `git config trim.bases develop,master` for a repository.\n'
        ' * `git config --global trim.bases develop,master` to set globally.\n'
        ' * `git trim --bases develop,master` to set temporarily.')
    raise Failure('No base branch is found!')


def glob_regex(pattern):
    """Glob matching with character classes and optional globstar directories."""
    result = ''
    i = 0
    while i < len(pattern):
        ch = pattern[i]
        if ch == '*':
            j = i
            while j < len(pattern) and pattern[j] == '*':
                j += 1
            if j-i >= 2 and j < len(pattern) and pattern[j] == '/':
                result += '(?:.*/)?'
                i = j + 1
                continue
            result += '.*'
            i = j
            continue
        if ch == '?':
            result += '.'
        elif ch == '[':
            j = i+1
            if j < len(pattern) and pattern[j] in '!^':
                j += 1
            if j < len(pattern) and pattern[j] == ']':
                j += 1
            j = pattern.find(']', j)
            if j < 0:
                result += r'\['
            else:
                content = pattern[i+1:j]
                if content.startswith('!'):
                    content = '^' + content[1:]
                elif content.startswith('^'):
                    content = '^' + content[1:]
                result += '[' + content.replace('\\', '\\\\') + ']'
                i = j
        elif ch == '\\' and i+1 < len(pattern):
            i += 1
            result += re.escape(pattern[i])
        else:
            result += re.escape(ch)
        i += 1
    try:
        return re.compile('^' + result + '$', re.DOTALL)
    except re.error:
        return re.compile(r'(?!)')


class MergeScanner:
    def __init__(self, repo, bases):
        self.repo = repo
        self.bases = list(dict.fromkeys(b.ref for b in bases))
        self.positive = set()
        self.cache = {}
        self.squashes = {}
        for base in self.bases:
            # Populate ancestry results first, as these require no patch comparison.
            self.positive.add(repo.refs[base].oid)
            for branch in repo.refs.values():
                if branch.oid not in self.positive and git('merge-base', '--is-ancestor', branch.oid, base).returncode == 0:
                    self.positive.add(branch.oid)

    def merged(self, branch):
        oid = branch.oid
        if oid in self.positive:
            return True
        if oid in self.cache:
            return self.cache[oid]
        for base in self.bases:
            p = git('rev-list', '--cherry-pick', '--right-only', '--no-merges', '-n1', base + '...' + oid)
            if p.returncode:
                status_error(p.returncode)
            if not p.stdout.strip():
                self.positive.add(oid)
                return True
            ancestor = gittext('merge-base', base, oid)
            if not ancestor:
                continue
            key = (ancestor, oid)
            squash = self.squashes.get(key)
            if not squash:
                tree = gittext('rev-parse', oid + '^{tree}')
                env = os.environ.copy()
                env.update(GIT_AUTHOR_NAME='Branch analysis', GIT_AUTHOR_EMAIL='analysis@localhost',
                           GIT_COMMITTER_NAME='Branch analysis', GIT_COMMITTER_EMAIL='analysis@localhost',
                           GIT_AUTHOR_DATE='2000-01-01T00:00:00+00:00', GIT_COMMITTER_DATE='2000-01-01T00:00:00+00:00')
                p = git('commit-tree', tree, '-p', ancestor, env=env, data=b'Combined changes\n')
                if p.returncode:
                    status_error(p.returncode)
                squash = text(p.stdout).strip()
                self.squashes[key] = squash
            p = git('rev-list', '--cherry-pick', '--right-only', '--no-merges', '-n1', base + '...' + squash)
            if p.returncode:
                status_error(p.returncode)
            if not p.stdout.strip():
                self.positive.add(oid)
                return True
        self.cache[oid] = False
        return False


@dataclass
class Candidate:
    branch: Branch
    kind: str
    remote: str = ''
    source: str = ''
    other: str = ''

    @property
    def category(self):
        return {'merged': 'merged', 'nontracking': 'merged non-tracking',
                'nonupstream': 'merged non-upstream', 'stray': 'stray',
                'diverged': 'diverged with ' + self.other,
                'direct': 'merged'}[self.kind]


class Plan:
    def __init__(self, repo, bases, protected, deletion, detach):
        self.repo = repo
        self.bases = bases
        self.patterns = [(p, glob_regex(p)) for p in protected]
        self.deletion = set(deletion)
        self.detach = detach
        self.notes = {}
        self.candidates = {}
        self.remove = {}
        self.extra = []
        self.skip_remote = []
        self.worktrees = {}
        p = git('worktree', 'list', '--porcelain')
        if p.returncode:
            status_error(p.returncode)
        path = ''
        for line in text(p.stdout).splitlines():
            if line.startswith('worktree '):
                path = line[len('worktree '):]
            if line.startswith('branch ') and os.path.realpath(path) != os.path.realpath(repo.root):
                self.worktrees[line[len('branch '):]] = path

    def allows(self, typ, remote=None):
        return (typ, remote) in self.deletion or (remote is not None and (typ, '*') in self.deletion)

    def add(self, branch, kind, remote='', source='', other=''):
        c = Candidate(branch, kind, remote, source, other)
        old = self.candidates.get(branch.ref)
        priority = {'merged': 5, 'nontracking': 5, 'nonupstream': 5, 'direct': 5, 'stray': 2, 'diverged': 1}
        if old is None or priority[kind] > priority[old.kind]:
            self.candidates[branch.ref] = c

    def classify(self):
        repo = self.repo
        tracking_scan = any(t in ('merged-local', 'merged-remote', 'stray', 'diverged') for t, _ in self.deletion)
        scanner = MergeScanner(repo, self.bases)
        upstreams = {b.upstream for b in repo.locals if b.tracking and not b.direct}
        for b in repo.locals:
            if not b.tracking:
                if not self.allows('local'):
                    self.notes[b.ref] = '*2'
                elif self.bases and scanner.merged(b):
                    self.add(b, 'nontracking')
                continue
            if not tracking_scan:
                self.notes[b.ref] = '*1'
                if b.upstream in repo.refs and not b.direct:
                    self.notes[b.upstream] = '*1'
                continue
            if not self.bases or b.unknown:
                continue
            if b.direct:
                self.classify_direct(b, scanner)
                continue
            up = repo.refs.get(b.upstream)
            lm = scanner.merged(b)
            remote, source = b.remote, b.remote_ref
            if up is None:
                self.add(b, 'merged' if lm else 'stray', remote, source)
                continue
            um = scanner.merged(up)
            if lm and um:
                self.add(b, 'merged', remote, source)
                self.add(up, 'merged', remote, source)
            elif lm:
                self.add(b, 'diverged', remote, source, up.ref)
                self.add(up, 'diverged', remote, source, b.ref)
            elif um:
                self.add(b, 'stray', remote, source)
                self.add(up, 'merged', remote, source)
        for b in repo.remote_branches:
            if b.ref in upstreams or not self.bases:
                continue
            remote, source = repo.remote_source(b.ref)
            if not self.allows('remote', remote):
                self.notes[b.ref] = '*3'
                self.skip_remote.append(remote)
            elif scanner.merged(b):
                self.add(b, 'nonupstream', remote, source)
        for ref, c in self.candidates.items():
            reason = self.keep_reason(c)
            if reason:
                if c.kind == 'merged' and (reason == 'base' or reason.startswith('tracks base ')):
                    self.notes[ref] = '[' + reason + ']'
                else:
                    self.notes[ref] = '[' + c.category + ', but: ' + reason + ']'
            else:
                self.notes.pop(ref, None)
                self.remove[ref] = c
        # A directly fetched branch is one unit: its local copy and remote ref.
        for b, pseudo in self.extra:
            if b.ref in self.remove:
                self.remove[pseudo.ref] = Candidate(pseudo, 'direct', b.remote, b.remote_ref)
            elif b.ref in self.notes:
                self.notes[pseudo.ref] = self.notes[b.ref]

    def classify_direct(self, b, scanner):
        p = git('ls-remote', b.remote, b.remote_ref)
        if p.returncode:
            status_error(p.returncode)
        lines = text(p.stdout).splitlines()
        remote_oid = next((line.split()[0] for line in lines if len(line.split()) >= 2 and line.split()[1] == b.remote_ref), '')
        lm = scanner.merged(b)
        if not remote_oid:
            self.add(b, 'merged' if lm else 'stray', b.remote, b.remote_ref)
            return
        if not lm:
            return
        pseudo = Branch('direct:' + b.remote + ':' + b.remote_ref, remote_oid)
        self.extra.append((b, pseudo))
        if remote_oid == b.oid:
            self.add(b, 'direct', b.remote, b.remote_ref)
        else:
            self.add(b, 'diverged', b.remote, b.remote_ref, b.remote + ', ' + b.remote_ref)

    def keep_reason(self, c):
        b = c.branch
        for base in self.bases:
            if b.local:
                if base.local == b.ref:
                    return 'base'
                if not base.local and b.upstream == base.ref:
                    return 'tracks base `' + base.pattern + '`'
            elif base.ref == b.ref:
                return 'base'
        for pattern, regex in self.patterns:
            if regex.fullmatch(b.name):
                return 'protected by a pattern `' + pattern + '`'
        if b.local:
            if b.ref == self.repo.head and not self.detach:
                return 'HEAD'
            if b.ref in self.worktrees:
                return 'worktree at ' + self.worktrees[b.ref]
        required = None
        if c.kind == 'stray':
            if not self.allows('stray'):
                required = 'stray'
        elif c.kind == 'diverged':
            if not self.allows('diverged', c.remote):
                required = 'diverged:' + c.remote
        elif c.kind == 'direct':
            if not self.allows('merged-remote', c.remote):
                required = 'merged-remote:' + c.remote
        elif c.kind == 'merged':
            if b.local:
                if not self.allows('merged-local'):
                    required = 'merged-local'
            elif not self.allows('merged-remote', c.remote):
                required = 'merged-remote:' + c.remote
        if required:
            return 'delete range `' + required + '` was not given'
        return None

    def report(self):
        out('Branches that will remain:')
        out('  local branches:')
        for b in self.repo.locals:
            if b.ref not in self.remove:
                out('    ' + b.name + (' ' + self.notes[b.ref] if b.ref in self.notes else ''))
        out('  remote references:')
        for b in self.repo.remote_branches:
            if b.ref not in self.remove:
                out('    ' + b.name + (' ' + self.notes[b.ref] if b.ref in self.notes else ''))
        for b, pseudo in sorted(self.extra, key=lambda pair: (pair[0].remote, pair[0].remote_ref)):
            if pseudo.ref not in self.remove:
                out('    ' + b.remote + ', ' + b.remote_ref + (' ' + self.notes[pseudo.ref] if pseudo.ref in self.notes else ''))
        skipped = set(self.notes.values())
        if skipped & {'*1', '*2', '*3'}:
            out('  Some branches are skipped. Consider following to scan them:')
            if '*1' in skipped:
                out("    *1: Add `--delete 'merged:*'` flag.")
            if '*2' in skipped:
                out("    *2: Set an upstream to make it a tracking branch or add `--delete 'local'` flag.")
            if '*3' in skipped:
                scope = self.skip_remote[0] if len(self.skip_remote) == 1 else '*'
                out("    *3: Make it upstream of a tracking branch or add `--delete 'remote:" + scope + "'` flag.")
        out()
        merged_local, merged_remote, stray, diverged = [], [], [], []
        for c in self.remove.values():
            b = c.branch
            if b.local:
                if c.kind == 'stray':
                    stray.append(b.name)
                else:
                    merged_local.append(b.name + (' (non-tracking)' if c.kind == 'nontracking' else ''))
            else:
                val = c.remote + ', ' + c.source
                if c.kind == 'nonupstream':
                    val += ' (non-upstream)'
                (diverged if c.kind in ('diverged', 'direct') else merged_remote).append(val)
        for heading, values in [('Delete merged local branches:', merged_local),
                                ('Delete merged remote refs:', merged_remote),
                                ('Delete stray local branches:', stray),
                                ('Delete diverged remote refs:', diverged)]:
            if values:
                out(heading)
                for v in sorted(set(values)):
                    out('  - ' + v)

    def execute(self, dry_run, confirm):
        if not self.remove:
            return
        if confirm and not dry_run:
            if not confirm_terminal():
                out('Cancelled')
                return
        remotes = {}
        locals = []
        for c in self.remove.values():
            if c.branch.local:
                locals.append(c.branch)
            else:
                remotes.setdefault(c.remote, set()).add(c.source)
        for remote in sorted(remotes):
            args = ['push', '--delete', '--no-verify']
            if dry_run:
                args.append('--dry-run')
            args.extend([remote, *sorted(remotes[remote])])
            visible_git(*args)
        if self.repo.head in self.remove:
            if dry_run:
                b = self.repo.refs[self.repo.head]
                summary = gittext('show', '-s', '--format=%s', b.oid)
                out("Note: switching to '" + self.repo.head + "' (dry run)")
                out("You are in 'detached HED' state... blah blah...")
                out('HEAD is now at ' + b.oid[:7] + (' ' + summary if summary else '') + ' (dry run)')
            else:
                visible_git('checkout', self.repo.head)
        if locals:
            names = sorted(set(b.name for b in locals))
            if dry_run:
                for name in names:
                    out('Delete branch ' + name + ' (dry run).')
            else:
                visible_git('branch', '--delete', '--force', *names)


def confirm_terminal():
    if not sys.stderr.isatty():
        raise Failure('IO error: not a terminal\n\nCaused by:\n    not a terminal')
    try:
        import termios
        fd = os.open('/dev/tty', os.O_RDWR)
    except OSError:
        raise Failure('IO error: not a terminal\n\nCaused by:\n    not a terminal')
    old = termios.tcgetattr(fd)
    try:
        new = termios.tcgetattr(fd)
        new[3] &= ~(termios.ECHO | termios.ICANON)
        new[6][termios.VMIN] = 1
        new[6][termios.VTIME] = 0
        termios.tcsetattr(fd, termios.TCSADRAIN, new)
        sys.stderr.write('Confirm? [y/N] \x1b[?25l'); sys.stderr.flush()
        while True:
            char = os.read(fd, 1)
            if char in (b'y', b'Y'):
                yes = True; break
            if char in (b'n', b'N', b'\n', b'\r', b''):
                yes = False; break
        sys.stderr.write('\r\x1b[2KConfirm? ' + ('yes' if yes else 'no') + '\n\x1b[?25h'); sys.stderr.flush()
        return yes
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)
        os.close(fd)


def check_remote_heads(repo):
    changes = []
    for remote in repo.remotes:
        p = git('ls-remote', '--symref', remote, 'HEAD')
        if p.returncode:
            status_error(p.returncode)
        target = ''
        for line in text(p.stdout).splitlines():
            if line.startswith('ref: ') and line.endswith('\tHEAD'):
                target = line[5:].split('\t', 1)[0]
                break
        if not target:
            raise Failure('HEAD not found on ' + remote)
        local = repo.refs.get('refs/remotes/' + remote + '/HEAD')
        if local and local.symbolic:
            _, prev = repo.remote_source(local.symbolic)
            if prev != target:
                changes.append((remote, prev, target))
    if changes:
        err('You are using default base branches, which is deduced from `refs/remotes/*/HEAD`s.\nHowever, they seems to be out of sync.')
        for remote, prev, target in changes:
            err(' * ' + remote + ': ' + prev + ' -> ' + target)
        err('You can sync them with these commands:')
        for remote, _, _ in changes:
            err(' > git remote set-head ' + remote + ' --auto')
        err('Or you can set base branches manually:\n'
            ' * `git config trim.bases develop,master` will set base branches for git-trim for a repository.\n'
            ' * `git config --global trim.bases develop,master` will set base branches for `git-trim` globally.\n'
            ' * `git trim --bases develop,master` will temporarily set base branches for `git-trim`')


def main():
    opts = parse_args(sys.argv[1:])
    repo = Repository()
    cfg = repo.config
    update = False if opts.no_update else cfg.boolean('trim.update', True)
    interval = opts.update_interval if opts.update_interval is not None else cfg.integer('trim.updateinterval', 5)
    if interval < 0:
        err("\nthread 'main' (" + str(os.getpid()) + ') panicked at src/config.rs:318:9:\n'
            '`git config trim.updateInterval` cannot be negative value\n'
            'note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace')
        raise Exit(101)
    confirm = False if opts.no_confirm else cfg.boolean('trim.confirm', True)
    detach = False if opts.no_detach else cfg.boolean('trim.detach', True)
    protected = opts.protected if opts.protected is not None else cfg.comma_list('trim.protected') or []
    protected = [p for p in protected if p]
    deletion = opts.delete
    if deletion is None:
        tokens = cfg.comma_list('trim.delete')
        if tokens is None:
            deletion = [('merged-local', None), ('merged-remote', 'origin')]
        else:
            deletion = [piece for token in tokens for piece in delete_token(token)]
    configured = False
    if opts.bases is not None:
        patterns = [p for p in opts.bases if p]
        if not patterns:
            patterns = repo.defaults()
    else:
        patterns = cfg.comma_list('trim.bases')
        configured = patterns is not None
        if patterns is None:
            patterns = repo.defaults()
    if not patterns:
        no_bases(repo, configured)
    if repo.bare:
        raise Failure('Bare repository is not supported')
    if not gittext('rev-parse', '--verify', 'HEAD'):
        raise Failure("reference '" + (repo.head or 'HEAD') + "' not found; class=Reference (4); code=UnbornBranch (-9)")
    repo.validate_branches()
    bases = repo.resolve_bases(patterns)
    if update:
        if not opts.dry_run:
            visible_git('remote', 'update', '--prune')
            repo.load_refs()
            repo.validate_branches()
            bases = repo.resolve_bases(patterns)
        out()
    plan = Plan(repo, bases, protected, deletion, detach)
    plan.classify()
    plan.report()
    plan.execute(opts.dry_run, confirm)
    if update:
        check_remote_heads(repo)


if __name__ == '__main__':
    try:
        main()
    except Failure as e:
        err('Error: ' + str(e))
        sys.exit(1)
    except Exit as e:
        sys.exit(e.code)
    except KeyboardInterrupt:
        sys.exit(130)
